(-93002,-93002,-93002,'REVIEW-2','2026-09-25','Foreign scope',100,'2026-01-01');
set local role authenticated;
set local request.jwt.claim.sub = '93000000-0000-0000-0000-000000000003';
select throws_ok($test$select save_quote_pdf_review(-93001,-93001,'2026-01-01','2026-01-01','2026-01-01','{"customer_scope":"Edited scope","quoted_price":250,"pdf_terms":"Edited terms","pdf_notes":"Public notes"}','{"first_name":"Edited customer"}','{"name":"Edited business"}')$test$,'42501',null,'role 3 cannot write this business');
set local request.jwt.claim.sub = '93000000-0000-0000-0000-000000000004';
select throws_ok($test$select save_quote_pdf_review(-93001,-93001,'2026-01-01','2026-01-01','2026-01-01','{"customer_scope":"Edited scope","quoted_price":250,"pdf_terms":"Edited terms","pdf_notes":"Public notes"}','{"first_name":"Edited customer"}','{"name":"Edited business"}')$test$,'42501',null,'role 4 cannot write this business');
set local request.jwt.claim.sub = '93000000-0000-0000-0000-000000000002';
select throws_ok($test$select save_quote_pdf_review(-93001,-93001,'2026-01-01','2026-01-01','2026-01-01','{"customer_scope":"Edited scope","quoted_price":250,"pdf_terms":"Edited terms","pdf_notes":"Public notes"}','{"first_name":"Edited customer"}','{"name":"Edited business"}')$test$,'42501',null,'employee cannot change business details');
