set local request.jwt.claim.sub = '93000000-0000-0000-0000-000000000001';
select throws_ok($test$select save_quote_pdf_review(-93001,-93002,'2026-01-01','2026-01-01','2026-01-01','{"customer_scope":"Edited scope","quoted_price":250,"pdf_terms":"Edited terms","pdf_notes":"Public notes"}','{"first_name":"Edited customer"}','{"name":"Edited business"}')$test$,'P0002',null,'foreign quote ID denied');
select throws_ok($test$select save_quote_pdf_review(-93001,-93001,'2025-01-01','2026-01-01','2026-01-01','{"customer_scope":"Edited scope","quoted_price":250,"pdf_terms":"Edited terms","pdf_notes":"Public notes"}','{"first_name":"Edited customer"}','{"name":"Edited business"}')$test$,'40001',null,'stale quote rejected');
select throws_ok($test$select save_quote_pdf_review(-93001,-93001,'2026-01-01','2026-01-01','2026-01-01','{"customer_scope":"Edited scope","quoted_price":250,"pdf_terms":"Edited terms","pdf_notes":"Public notes"}','{"first_name":""}','{"name":"Edited business"}')$test$,'23514',null,'invalid customer rolls back business update');
